struct alignas(32) R {float x;};
struct P {__storage__ R *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {p->data[0].x=1; p->data[1].x=2;}

constexpr float table[4]={1,2,3,4};
struct P {__storage__ float *data; unsigned idx;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {p->data[0]=table[p->idx&3];}

struct R { float x=1; private: float y=2; };
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R a; auto r=normalize(a); p->data[0]=r.x;}

struct R {float x,y,z; R():x(1),y(2),z(3){} };
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R a; auto r=normalize(a); p->data[0]=r.x;}

struct R {const float x; float y,z;};
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R a{1,2,3}; auto r=normalize(a); p->data[0]=r.x;}

float min(float a,float b){return a+b;}
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {p->data[0]=min(1.0f,2.0f);}

float normalize(float x){return x+1;}
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {p->data[0]=normalize(2.0f);}

namespace functions {float normalize(float x){return x+1;}}
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {p->data[0]=functions::normalize(2.0f);}

struct R {virtual float value(){return 1;}};
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R a; p->data[0]=a.value();}

float helper(float x){return x+1;}
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {auto f=&helper; p->data[0]=f(2);}

struct alignas(32) R {float x;};
struct P {__storage__ float *data; unsigned idx;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R a; a.x=p->idx; p->data[0]=a.x;}

struct R{__storage__ float *pointer;};
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R a{p->data}; *a.pointer=2;}

struct R{float x,y,z;};
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {auto r=normalize(R{1,2,3}); p->data[0]=r.x;}

struct R{float x; float get()const{return x*2;}};
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R r{p->data[0]}; p->data[0]=r.get();}

void helper(__storage__ __align__(32) float *p){*p=1;}
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {helper(p->data);}

struct R{alignas(32) float x;};
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R r; r.x=p->data[0]; p->data[0]=r.x;}

__storage__ float *helper(__storage__ float *p){return p+1;}
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {auto q=helper(p->data); *q=1;}

struct alignas(32) R{float a[3];};
struct P {__storage__ float *data; unsigned idx;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {R r; for(unsigned i=0;i<3;i++)r.a[i]=p->data[i]; p->data[0]=r.a[p->idx%3];}

volatile float x=1;
struct P {__storage__ float *data;};
__compute__ __workgroup_size__(1,1,1) void main(__push_constant__ const P *p) {p->data[0]=x;}
